window.AKT = window.AKT || {};
window.AKT.library = [{"kind":"book","title":{"ar":"الثلاثية","en":"The Cairo Trilogy"},"by":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"year":1956,"said":{"ar":"عدّها تحفة كثيفة وممتعة جدًا في الوقت نفسه، ورأى أن محفوظ يستحق تقديرًا أكبر.","en":"He called it a dense masterpiece that is also hugely enjoyable, and said Mahfouz deserves more credit."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"الشحاذ","en":"The Beggar"},"by":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"year":1965,"said":{"ar":"قال إنها سببت له أزمة وجودية لا بأس بها، وإن سحر «الطريق» و«اللص والكلاب» يصعب الإفلات منه.","en":"He said it gave him a real existential crisis, and that the spell of The Search and The Thief and the Dogs is hard to escape."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"رحلة ابن فطومة","en":"The Journey of Ibn Fattouma"},"by":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"year":1983,"said":{"ar":"رأى أن «السيميائي» لكويلو نسخة باهتة منها.","en":"He said Coelho's The Alchemist is only a pale copy of it."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"writer","title":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"by":null,"year":null,"said":{"ar":"انحاز إليه في معركة «الشعر أم الرواية» ورأى أنه كان على حق في دفاعه عن فن الرواية.","en":"In the old poetry-versus-novel quarrel he sided with Mahfouz, who he felt was right to defend the novel."},"post":"8408614563219517768","source":"https://aktowfik.blogspot.com/2015/06/blog-post_16.html"},{"kind":"book","title":{"ar":"الجريمة والعقاب","en":"Crime and Punishment"},"by":{"ar":"فيودور دستويفسكي","en":"Fyodor Dostoevsky"},"year":1866,"said":{"ar":"عمل عملاق أدخله عالم الأدب الروسي، يجعلك تسكن عقل البطل.","en":"A giant of a book that pulled him into Russian literature by putting you inside the hero's mind."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"writer","title":{"ar":"أنطون تشيخوف","en":"Anton Chekhov"},"by":null,"year":null,"said":{"ar":"أقوى من أثّر فيه مبكرًا، حتى صار يرى الحياة بعين «تشيخوفية»، ويسميه سيد الأطباء الأدباء.","en":"His strongest early influence — he came to see life through a 'Chekhovian' eye — and the master of doctor-writers."},"post":"4386207679737144707","source":"https://aktowfik.blogspot.com/2016/10/blog-post_5.html"},{"kind":"book","title":{"ar":"التفاحة والجمجمة","en":"The Apple and the Skull"},"by":{"ar":"محمد عفيفي","en":"Mohamed Afifi"},"year":null,"said":{"ar":"رواية عميقة رمزية عن الحياة والوجود، وفي الوقت نفسه مضحكة جدًا.","en":"Deep and symbolic about life and existence, yet very funny."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"ابنة الحظ","en":"Daughter of Fortune"},"by":{"ar":"إيزابيل الليندي","en":"Isabel Allende"},"year":1999,"said":{"ar":"من أجمل ما قرأ في سن متأخرة، وذكّرته بمتعة القراءة نفسها (ومعها «صورة قديمة»).","en":"One of the best books of his later reading life — with Portrait in Sepia — it reminded him of the sheer joy of reading."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"1984","en":"Nineteen Eighty-Four"},"by":{"ar":"جورج أورويل","en":"George Orwell"},"year":1949,"said":{"ar":"مزيج من الخيال العلمي والمغامرة والسياسة، ترجمه بنفسه إلى العربية، ويسمي أورويل عبقريًا.","en":"A blend of science fiction, adventure and politics that he translated himself; he called Orwell a genius."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"ميزري (الشيطانة)","en":"Misery"},"by":{"ar":"ستيفن كينج","en":"Stephen King"},"year":1987,"said":{"ar":"أول رواية قرأها لكينج أثناء عمله في السعودية، ثم ترجمها بعنوان «الشيطانة».","en":"The first King novel he read, while working in Saudi Arabia; he later translated it as Al-Shaytana."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"writer","title":{"ar":"ستيفن كينج","en":"Stephen King"},"by":null,"year":null,"said":{"ar":"قال إنه مقتنع تمامًا بفكرة كينج أن كاتب الرعب يرسم «دائرة سحرية» تحميه.","en":"He said he fully shared King's idea that a horror writer draws a 'magic circle' to protect himself and his own."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"ثم لم يبق أحد (جزيرة الموت)","en":"And Then There Were None"},"by":{"ar":"أجاثا كريستي","en":"Agatha Christie"},"year":1939,"said":{"ar":"أول رواية قرأها لكريستي، وأبقته مذعورًا لا ينام أيامًا.","en":"His first Christie novel — it kept him frightened and sleepless for days."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"حذار من الشفقة","en":"Beware of Pity"},"by":{"ar":"ستيفان زفايج","en":"Stefan Zweig"},"year":1939,"said":{"ar":"رواية عن الشفقة التي تدفع إلى تضحية تحطم الطرفين، وذكر معها «ماجلان» و«لاعب الشطرنج».","en":"A novel on how pity-driven sacrifice can wreck both sides; he also named Magellan and The Chess Player among Zweig's wonders."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"writer","title":{"ar":"يوسف إدريس","en":"Yusuf Idris"},"by":null,"year":null,"said":{"ar":"«عبقري لم يجد الزمان بمثله إلا نادرًا»، ورأى نوبل أضيق أفقًا من أن تتشرف به.","en":"'A genius the age rarely produces' — he thought the Nobel too narrow to have honoured him."},"post":"5228172907938781168","source":"https://aktowfik.blogspot.com/2014/07/3.html"},{"kind":"book","title":{"ar":"العيب","en":"Al-Eib (The Shame)"},"by":{"ar":"يوسف إدريس","en":"Yusuf Idris"},"year":1962,"said":{"ar":"عدّها مع «الحرام» من الروايات المهمة التي أثرت فيه.","en":"He listed it, with Al-Haram, among the novels that marked him."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"ثلاثية غرناطة","en":"Granada Trilogy"},"by":{"ar":"رضوى عاشور","en":"Radwa Ashour"},"year":1994,"said":{"ar":"تنقلك إلى الأندلس الساقطة، وألهمت جيلًا من الرواية التاريخية.","en":"It carries you into fallen Andalusia and inspired a generation of historical fiction."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"مدام بوفاري","en":"Madame Bovary"},"by":{"ar":"جوستاف فلوبير","en":"Gustave Flaubert"},"year":1857,"said":{"ar":"أبهرته في شبابه بتصويرها النفسي للبطلة، وحاول أن يكتب مثل فلوبير وفشل.","en":"It dazzled him in his youth with its psychological portrait; he tried to write like Flaubert and failed."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"القمر وستة بنسات","en":"The Moon and Sixpence"},"by":{"ar":"سومرست موم","en":"W. Somerset Maugham"},"year":1919,"said":{"ar":"ممتعة للغاية وشبه ملحمية، عن محاسب يترك حياته ليرسم في تاهيتي.","en":"Hugely entertaining and almost epic — the clerk who drops everything to paint in Tahiti."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"المسيح يصلب من جديد","en":"Christ Recrucified (The Greek Passion)"},"by":{"ar":"نيكوس كازانتزاكيس","en":"Nikos Kazantzakis"},"year":1948,"said":{"ar":"رواية كثيفة لا تُنسى.","en":"A dense, unforgettable novel."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"other","title":{"ar":"سلسلة «أولادنا»","en":"Dar al-Maaref's 'Awladuna' series"},"by":null,"year":null,"said":{"ar":"عرّفته بـ«جزيرة الكنز» و«مونفليت» و«آلة الزمن» وغيرها، وأدفأت جيلًا كاملًا.","en":"It introduced him to Treasure Island, Moonfleet, The Time Machine and more, and warmed a whole generation."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"writer","title":{"ar":"جوزيه ساراماجو","en":"José Saramago"},"by":null,"year":null,"said":{"ar":"سماه «الأديب العظيم»، وأُعجب بسخرية «البصيرة» وفرح لأن فكرة روايته اقتربت من «الطوف الحجري».","en":"He called him 'this great writer', admired the satire of Seeing, and was glad his own idea came close to The Stone Raft."},"post":"4067535336538242235","source":"https://aktowfik.blogspot.com/2011/10/blog-post_10.html"},{"kind":"writer","title":{"ar":"عزيز نيسين","en":"Aziz Nesin"},"by":null,"year":null,"said":{"ar":"الأديب التركي «الرائع» الذي رأى أنه يكتب عن مصر أكثر مما يكتب عن تركيا.","en":"The 'wonderful' Turkish satirist who, he felt, was really writing about Egypt."},"post":"3007787008187835519","source":"https://aktowfik.blogspot.com/2010/07/blog-post_06.html"},{"kind":"book","title":{"ar":"بيت في الدنيا وبيت في الحنين","en":"A House in the World and a House in Longing"},"by":{"ar":"إبراهيم الكوني","en":"Ibrahim al-Koni"},"year":null,"said":{"ar":"سماها ملحمة، وقال إن الكوني «أديب مهم فعلًا وله عالم شديد الثراء والتفرد».","en":"He called it an epic and al-Koni a truly important writer with a rich, unique world."},"post":"4810671056694157213","source":"https://aktowfik.blogspot.com/2007/02/blog-post.html"},{"kind":"book","title":{"ar":"قناع الموت الأحمر","en":"The Masque of the Red Death"},"by":{"ar":"إدجار آلان بو","en":"Edgar Allan Poe"},"year":1842,"said":{"ar":"من كلاسيكيات الأدب العالمي وأدق نموذج للرعب القوطي، لا يتخيله إلا عقل عبقري.","en":"A world classic and the purest example of Gothic horror, imaginable only by a genius."},"post":"2586648679223311039","source":"https://aktowfik.blogspot.com/2017/09/blog-post.html"},{"kind":"book","title":{"ar":"شخصية مصر","en":"The Personality of Egypt"},"by":{"ar":"جمال حمدان","en":"Gamal Hamdan"},"year":null,"said":{"ar":"كتاب صغير رشيق قرأه مبكرًا، يحمل قدرًا هائلًا من الجهد والجدية، وسمّى صاحبه «عبقري في مصر».","en":"A small, elegant book he met young, full of effort and seriousness; he called its author 'a genius in Egypt'."},"post":"415596431333853349","source":"https://aktowfik.blogspot.com/2018/02/blog-post_10.html"},{"kind":"book","title":{"ar":"رحيق العمر","en":"Rahiq al-Umr"},"by":{"ar":"جلال أمين","en":"Galal Amin"},"year":2010,"said":{"ar":"«درة جديرة بأن تُقرأ»، أعجبته صراحتها وبناؤها غير المألوف.","en":"'A gem worth reading' — he praised its frankness and unusual structure."},"post":"3747681047566908249","source":"https://aktowfik.blogspot.com/2010/02/blog-post_24.html"},{"kind":"book","title":{"ar":"كان صبيًا في السبعينيات","en":"He Was a Boy in the Seventies"},"by":{"ar":"محمود عبد الشكور","en":"Mahmoud Abdel Shakour"},"year":null,"said":{"ar":"أحب الكتاب كثيرًا لأنه كان هو أيضًا صبيًا في السبعينيات.","en":"He loved it very much — he too had been a boy in the seventies."},"post":"5272186971730117760","source":"https://aktowfik.blogspot.com/2016/04/blog-post_67.html"},{"kind":"book","title":{"ar":"المغامرون الخمسة","en":"The Five Adventurers"},"by":{"ar":"محمود سالم","en":"Mahmoud Salem"},"year":null,"said":{"ar":"سلسلة ممتعة «أبدعتها عبقرية محمود سالم»، تابع فيها تختخ تلميذًا في الإعدادية.","en":"A delightful series 'created by the genius of Mahmoud Salem' that he followed as a schoolboy."},"post":"4940629198902647210","source":"https://aktowfik.blogspot.com/2010/09/blog-post_29.html"},{"kind":"other","title":{"ar":"تان تان","en":"Tintin"},"by":{"ar":"هيرجيه","en":"Hergé"},"year":null,"said":{"ar":"قال إنه «جزء حقيقي بالغ الأهمية من ذاتي»، وما زال يحتفظ بكل أعداده.","en":"He called it a truly vital part of himself and still kept every issue."},"post":"8948120280206707948","source":"https://aktowfik.blogspot.com/2023/04/blog-post.html"},{"kind":"other","title":{"ar":"مجلة سمير (عصرها الذهبي)","en":"Samir magazine (its golden age)"},"by":null,"year":null,"said":{"ar":"أعجبه أن فنانيها كانوا يحبون ما يفعلونه فعلًا وصنعوا أسلوبًا خاصًا بعيدًا عن التقليد.","en":"He admired that its artists truly loved their work and built a style of their own."},"post":"2485621767829887088","source":"https://aktowfik.blogspot.com/2010/01/blog-post_29.html"},{"kind":"other","title":{"ar":"كاريكاتير مصطفى حسين","en":"Mostafa Hussein's cartoons"},"by":{"ar":"مصطفى حسين","en":"Mostafa Hussein"},"year":null,"said":{"ar":"رحلة حب طويلة مع خطوطه منذ طفولته، وسمّاها «موهبة مذهلة».","en":"A lifelong love of his line since childhood — 'an amazing talent'."},"post":"7407275423388885946","source":"https://aktowfik.blogspot.com/2014/08/blog-post_28.html"},{"kind":"writer","title":{"ar":"بيرم التونسي","en":"Bayram al-Tunisi"},"by":null,"year":null,"said":{"ar":"«عمنا وتاج راسنا وأعظم فنانينا»، بعين حساسة ساخرة ما زالت أبياته تنطبق على اليوم.","en":"'Our uncle, the crown on our heads and our greatest artist', whose verses still fit today."},"post":"4623244713135040727","source":"https://aktowfik.blogspot.com/2009/08/blog-post.html"},{"kind":"writer","title":{"ar":"صلاح جاهين","en":"Salah Jahin"},"by":null,"year":null,"said":{"ar":"يسميه «الشاعر العظيم» ويستشهد بفوازير «الخاطبة».","en":"He calls him 'the great poet' and quotes his Al-Khatba riddles."},"post":"87429429657316372","source":"https://aktowfik.blogspot.com/2014/01/blog-post_28.html"},{"kind":"writer","title":{"ar":"عبد الرحمن الأبنودي","en":"Abdel Rahman El-Abnoudi"},"by":null,"year":null,"said":{"ar":"رثاه بأنه «جزء من نسيج حياتنا والهواء الذي نتنفسه».","en":"He mourned him as part of the fabric of our lives and the air we breathe."},"post":"9009797136906452940","source":"https://aktowfik.blogspot.com/2015/04/blog-post_30.html"},{"kind":"music","title":{"ar":"زهرة المدائن (لأجلك يا مدينة الصلاة)","en":"Zahrat al-Madaen"},"by":{"ar":"فيروز","en":"Fairuz"},"year":1967,"said":{"ar":"سمعها تلميذًا في السبعينيات فأبكته، وطلب من قرائه الاستماع إليها مع المقال.","en":"She made him cry as a schoolboy in the seventies; he asked readers to play it while reading."},"post":"5442812717040122944","source":"https://aktowfik.blogspot.com/2015/10/blog-post_18.html"},{"kind":"film","title":{"ar":"المواطن كين","en":"Citizen Kane"},"by":{"ar":"أورسون ويلز","en":"Orson Welles"},"year":1941,"said":{"ar":"«تحفة أورسون ويلز» وقصتها المؤثرة عن «روزباد».","en":"'Orson Welles's masterpiece' and its moving Rosebud story."},"post":"1042801910774120853","source":"https://aktowfik.blogspot.com/2010/10/blog-post_31.html"},{"kind":"film","title":{"ar":"سفر الرؤيا الآن","en":"Apocalypse Now"},"by":{"ar":"فرانسيس فورد كوبولا","en":"Francis Ford Coppola"},"year":1979,"said":{"ar":"تحفة ظلت مشاهدها تلاحقه، ومارلون براندو أدى دوره «بامتياز».","en":"A masterpiece whose scenes haunted him; Brando played his part superbly."},"post":"1629099072177474895","source":"https://aktowfik.blogspot.com/2014/10/blog-post_63.html"},{"kind":"film","title":{"ar":"دكتور سترينجلوف","en":"Dr. Strangelove"},"by":{"ar":"ستانلي كوبريك","en":"Stanley Kubrick"},"year":1964,"said":{"ar":"مشهد الطيار الممتطي للقنبلة «يلخص العسكرية الأمريكية ببلاغة».","en":"The bomb-riding finale 'eloquently sums up American militarism'."},"post":"2296881967953815321","source":"https://aktowfik.blogspot.com/2014/10/blog-post_12.html"},{"kind":"film","title":{"ar":"مفقود","en":"Missing"},"by":{"ar":"كوستا جافراس","en":"Costa-Gavras"},"year":1982,"said":{"ar":"«هذا الفيلم الرائع» عن صحفي أمريكي اختفى في انقلاب تشيلي.","en":"'This wonderful film' about an American journalist who vanished in Chile's coup."},"post":"4551775308863126111","source":"https://aktowfik.blogspot.com/2016/04/blog-post_0.html"},{"kind":"film","title":{"ar":"أماديوس","en":"Amadeus"},"by":{"ar":"ميلوش فورمان","en":"Miloš Forman"},"year":1984,"said":{"ar":"أوصى بمشاهدته، ورأى سالييري فيه محبًا صادقًا للفن رغم غيرته.","en":"He urged readers to watch it and saw its Salieri as a sincere lover of art despite his envy."},"post":"7108067586238926893","source":"https://aktowfik.blogspot.com/2016/09/blog-post_12.html"},{"kind":"film","title":{"ar":"يوم طفت الأسماك ميتة","en":"The Day the Fish Came Out"},"by":{"ar":"مايكل كاكويانيس","en":"Michael Cacoyannis"},"year":1967,"said":{"ar":"من صنع «عبقري السينما اليونانية»، بنظرة حادة إلى قلق الحرب النووية وموسيقى ثيودوراكيس.","en":"By 'the genius of Greek cinema' — a sharp take on nuclear dread, with Theodorakis's music."},"post":"3492198745992612059","source":"https://aktowfik.blogspot.com/2015/12/blog-post_25.html"},{"kind":"film","title":{"ar":"سينما باراديسو","en":"Cinema Paradiso"},"by":{"ar":"جوزيبي تورناتوري","en":"Giuseppe Tornatore"},"year":1988,"said":{"ar":"رأى فيه العشق المهووس للسينما الذي عاشه هو طفلًا.","en":"He saw in it the obsessive childhood love of cinema he had lived himself."},"post":"5659497887479625762","source":"https://aktowfik.blogspot.com/2021/03/blog-post.html"},{"kind":"film","title":{"ar":"جرايندهاوس","en":"Grindhouse"},"by":{"ar":"كوينتن تارانتينو وروبرت رودريجيز","en":"Quentin Tarantino & Robert Rodriguez"},"year":2007,"said":{"ar":"أعجبه كتحية لأفلام السبعينيات بخدوش الشريط وإعلاناته الزائفة.","en":"He admired it as a tribute to 1970s exploitation films, scratches and fake trailers included."},"post":"5659497887479625762","source":"https://aktowfik.blogspot.com/2021/03/blog-post.html"},{"kind":"film","title":{"ar":"دراكيولا (أفلام هامر، كريستوفر لي)","en":"Dracula — Hammer films with Christopher Lee"},"by":{"ar":"تيرينس فيشر","en":"Terence Fisher"},"year":1958,"said":{"ar":"سحرته أفلام هامر طفلًا، وكان دراكيولا كريستوفر لي مرعبًا.","en":"Hammer horror spellbound him as a child; Christopher Lee's Dracula was terrifying."},"post":"5659497887479625762","source":"https://aktowfik.blogspot.com/2021/03/blog-post.html"},{"kind":"other","title":{"ar":"سامي السلاموني","en":"Sami El-Salamouni (film critic)"},"by":null,"year":null,"said":{"ar":"«كان طفلًا مندهشًا يعشق السينما بجنون»، وكتاباته تستحق أن تُجمع في كتاب.","en":"'A wide-eyed child madly in love with cinema' whose articles deserve a book."},"post":"6944396326437494134","source":"https://aktowfik.blogspot.com/2010/08/blog-post_5530.html"},{"kind":"other","title":{"ar":"مارا/صاد","en":"Marat/Sade"},"by":{"ar":"بيتر فايس","en":"Peter Weiss"},"year":1963,"said":{"ar":"مسرحية فرق الكلية، قال إن «النص ما زال في غاية القوة» ونصح بقراءته.","en":"A college-theatre favourite whose text, he said, is still extremely powerful — read it."},"post":"8594911836508637055","source":"https://aktowfik.blogspot.com/2013/12/blog-post_5.html"},{"kind":"book","title":{"ar":"بلد العميان","en":"The Country of the Blind"},"by":{"ar":"هـ. ج. ويلز","en":"H. G. Wells"},"year":1904,"said":{"ar":"«قصة قصيرة رائعة» لرائد الخيال العلمي، تذكّرها وهو يرفض الرشاوى طبيبًا في الريف.","en":"A 'wonderful short story' he recalled while refusing bribes as a rural doctor."},"post":"4197653838619665368","source":"https://aktowfik.blogspot.com/2011/01/blog-post.html"},{"kind":"book","title":{"ar":"إذا","en":"If—"},"by":{"ar":"روديارد كبلنج","en":"Rudyard Kipling"},"year":1910,"said":{"ar":"من أجمل ما قرأ، رغم نقده لكبلنج بوصفه بوق الإمبراطورية.","en":"Among the most beautiful things he had read, though he faulted Kipling as the Empire's trumpet."},"post":"4197653838619665368","source":"https://aktowfik.blogspot.com/2011/01/blog-post.html"},{"kind":"book","title":{"ar":"النطاق السام","en":"The Poison Belt"},"by":{"ar":"آرثر كونان دويل","en":"Arthur Conan Doyle"},"year":1913,"said":{"ar":"«رواية ممتعة» اتخذها مجازًا لمصر التي تعبر نطاقًا سامًا.","en":"'An enjoyable novel' he used as a metaphor for Egypt passing through a toxic zone."},"post":"3472772353612461876","source":"https://aktowfik.blogspot.com/2015/02/blog-post.html"},{"kind":"book","title":{"ar":"السيدة أم النمر؟","en":"The Lady, or the Tiger?"},"by":{"ar":"فرانك ستوكتون","en":"Frank R. Stockton"},"year":1882,"said":{"ar":"قصة شهيرة شحذت ذكاء القراء وصار عنوانها مثلًا للمعضلة بلا حل.","en":"A famous story that sharpened readers' wits; its title became shorthand for an insoluble dilemma."},"post":"434815869563967333","source":"https://aktowfik.blogspot.com/2014/10/blog-post_14.html"},{"kind":"writer","title":{"ar":"بلال فضل","en":"Belal Fadl"},"by":null,"year":null,"said":{"ar":"«أحببت كتابات بلال فضل كثيرًا» واعتبره من أفضل الأقلام التي قرأها.","en":"He loved Belal Fadl's writing and counted him among the best pens he had read."},"post":"2111357844574046554","source":"https://aktowfik.blogspot.com/2016/05/blog-post.html"},{"kind":"book","title":{"ar":"هاري بوتر","en":"Harry Potter"},"by":{"ar":"ج. ك. رولينج","en":"J. K. Rowling"},"year":null,"said":{"ar":"قرأ السلسلة «واستمتعت بها جدًا»، وإن شك في نجاحها عربيًا.","en":"He read the series and enjoyed it greatly, though he doubted it would catch on in Arabic."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"العنكبوت","en":"The Spider"},"by":{"ar":"مصطفى محمود","en":"Mustafa Mahmoud"},"year":1965,"said":{"ar":"يعتبرها «مرعبة في مواضع كثيرة»، من النماذج النادرة للرعب العربي.","en":"He found it frightening in many places — a rare Arabic horror novel."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"وردة","en":"Warda"},"by":{"ar":"صنع الله إبراهيم","en":"Sonallah Ibrahim"},"year":2000,"said":{"ar":"قال إنها خرجت «رائعة» برغم ما فيها من جرأة.","en":"He said it came out wonderful despite its frank content."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"عمارة يعقوبيان","en":"The Yacoubian Building"},"by":{"ar":"علاء الأسواني","en":"Alaa Al Aswany"},"year":2002,"said":{"ar":"قرنها بـ«وردة» روايةً رائعة برغم جرأتها.","en":"He paired it with Warda as a wonderful novel despite its frankness."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"music","title":{"ar":"ما بيكر","en":"Ma Baker"},"by":{"ar":"بوني إم","en":"Boney M."},"year":1977,"said":{"ar":"تتبّع لحنها إلى الأغنية التونسية «سيدي منصور»، وتذكّر أن فرقة «الجيتس» المصرية حوّلتها إلى «أوكي أوكي».","en":"He traced its tune to the Tunisian song Sidi Mansour, and recalled the Egyptian band the Jets turning it into \"OK OK\"."},"post":null,"source":"https://www.masress.com/boswtol/1110","from":"nashawat-qadima"},{"kind":"music","title":{"ar":"تشيكتيتا","en":"Chiquitita"},"by":{"ar":"آبا","en":"ABBA"},"year":1979,"said":{"ar":"غنّتها آبا في حفل خيري لليونيسف، واسمها بالإسبانية «الفتاة الصغيرة».","en":"ABBA sang it at a UNICEF charity concert; its name is Spanish for \"little girl\"."},"post":null,"source":"https://www.masress.com/boswtol/8492","from":"nashawat-qadima"},{"kind":"music","title":{"ar":"بالأمس عندما كنت صغيرًا","en":"Yesterday, When I Was Young"},"by":{"ar":"شارل أزنافور","en":"Charles Aznavour"},"year":1964,"said":{"ar":"أغنية أزنافور الفرنسية «Hier encore» التي نُقلت إلى الإنجليزية والإيطالية، قدّمها بصوت إدي أرنولد.","en":"Aznavour's French \"Hier encore\", carried into English and Italian; he gave it in Eddy Arnold's voice."},"post":null,"source":"https://www.masress.com/boswtol/8107","from":"nashawat-qadima"},{"kind":"music","title":{"ar":"أبهر أنفاسي","en":"Take My Breath Away"},"by":{"ar":"برلين","en":"Berlin"},"year":1986,"said":{"ar":"رأى أنها تلخّص حقبة الثمانينيات كلها.","en":"He felt it could sum up the whole of the eighties."},"post":null,"source":"https://www.masress.com/boswtol/18884","from":"nashawat-qadima"},{"kind":"music","title":{"ar":"طوبة أخرى في الجدار","en":"Another Brick in the Wall"},"by":{"ar":"بينك فلويد","en":"Pink Floyd"},"year":1979,"said":{"ar":"قرأها تمرّدًا على المدرسة والتعليم بالتلقين.","en":"He read it as a revolt against school and learning by rote."},"post":null,"source":"https://www.masress.com/boswtol/19173","from":"nashawat-qadima"},{"kind":"music","title":{"ar":"في عام 2525","en":"In the Year 2525"},"by":{"ar":"زاجر وإيفانز","en":"Zager and Evans"},"year":1969,"said":{"ar":"تتخيّل الإنسان عام 2525 وما بعده، ثم تدرك في آخرها أنها دورة حياة تبدأ من جديد.","en":"It imagines man in 2525 and after, and at its end you see it is a cycle that starts all over again."},"post":null,"source":"https://global.al-balsam.com/products/%D9%86%D8%B4%D9%88%D8%A7%D8%AA-%D9%82%D8%AF%D9%8A%D9%85%D8%A9","from":"nashawat-qadima"}];
